	it("does not let stale widget cache cancel a new capability restore", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", { configurable: true, value: compatParent });
		type RestoreResult = { isError: false; structuredContent: { found: true; tool_name: string; data: { title: string }; view_state: Record<string, never> } };
		let resolveNext!: (value: RestoreResult) => void;
		const nextRestore = new Promise<RestoreResult>((resolve) => { resolveNext = resolve; });
		bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
			if (name === "restore_lobu_app_result" && args.snapshot_capability === "old-token") {
				return { isError: false, structuredContent: { found: true, tool_name: "query_sdk", data: { title: "Old card" }, view_state: {} } };
			}
			if (name === "restore_lobu_app_result" && args.snapshot_capability === "new-token") return nextRestore;
			if (name === "save_lobu_app_state") return { isError: false, structuredContent: { saved: true } };
			return { isError: false, structuredContent: { found: false, view_state: {} } };
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{ title: string }>();
			return <span>{data?.title ?? "No result"}</span>;
		}
		render(<Provider devMock={{ title: "Development" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) handler({ structuredContent: { title: "Old card" }, _meta: { "lobu/mcp-app-snapshot-capability": "old-token" } });
		});
		expect(await screen.findByText("Old card")).toBeInTheDocument();
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) handler({ structuredContent: {}, _meta: { "lobu/mcp-app-snapshot-capability": "new-token" } });
		});
		await waitFor(() => expect(bridge.callServerTool).toHaveBeenCalledWith({ name: "restore_lobu_app_result", arguments: { snapshot_capability: "new-token" } }));
		expect(await screen.findByText("No result")).toBeInTheDocument();
		act(() => {
			window.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: { widgetState: { privateContent: { lobuViewSnapshot: { version: 1, data: { title: "Old card" } } } } } } }));
		});
		expect(await screen.findByText("Old card")).toBeInTheDocument();
		await act(async () => {
			resolveNext({ isError: false, structuredContent: { found: true, tool_name: "query_sdk", data: { title: "New card" }, view_state: {} } });
			await nextRestore;
		});
		expect(await screen.findByText("New card")).toBeInTheDocument();
		expect(screen.queryByText("Old card")).not.toBeInTheDocument();
	});
});
