	it("restores a capability-only standard result after an explicit compatibility clear", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), { location: { origin: "https://chatgpt.com" } });
		Object.defineProperty(window, "parent", { configurable: true, value: compatParent });
		bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
			if (name === "restore_lobu_app_result" && args.snapshot_capability === "new-token") return { isError: false, structuredContent: { found: true, tool_name: "query_sdk", data: { title: "New card" }, view_state: {} } };
			return { isError: false };
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() { const { data } = useMcpApp<{ title: string }>(); return <span>{data?.title ?? "No result"}</span>; }
		render(<Provider devMock={{ title: "Development" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() => { for (const handler of bridge.listeners.get("toolresult") ?? []) handler({ structuredContent: { title: "Old card" } }); });
		expect(await screen.findByText("Old card")).toBeInTheDocument();
		act(() => { window.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: { toolOutput: null } } })); });
		expect(await screen.findByText("No result")).toBeInTheDocument();
		act(() => { for (const handler of bridge.listeners.get("toolresult") ?? []) handler({ structuredContent: {}, _meta: { "lobu/mcp-app-snapshot-capability": "new-token" } }); });
		expect(await screen.findByText("New card")).toBeInTheDocument();
	});

	it("does not save partial state after a capability restore fails", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), { location: { origin: "https://chatgpt.com" } });
		Object.defineProperty(window, "parent", { configurable: true, value: compatParent });
		Object.defineProperty(window, "openai", { configurable: true, value: {
			widgetState: { privateContent: { lobuViewSnapshot: { version: 1, data: { title: "Cached card" } } } },
			toolResponseMetadata: { mcp_tool_result: { _meta: { "lobu/mcp-app-snapshot-capability": "restore-token" } } },
		} });
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") throw new Error("temporary");
			if (name === "save_lobu_app_state") return { isError: false, structuredContent: { saved: true } };
			return { isError: false };
		});
		const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
		try {
			const { Provider, useMcpApp } = await import("./host");
			function Probe() { const { data, setViewState } = useMcpApp<{ title: string }>(); return <><span>{data?.title}</span><button type="button" onClick={() => setViewState("details.open", true)}>Edit</button></>; }
			render(<Provider devMock={{ title: "Development" }}><Probe /></Provider>);
			expect(await screen.findByText("Cached card")).toBeInTheDocument();
			await waitFor(() => expect(warn).toHaveBeenCalled());
			fireEvent.click(screen.getByRole("button", { name: "Edit" }));
			await act(() => new Promise((resolve) => window.setTimeout(resolve, 300)));
			expect(bridge.callServerTool.mock.calls.filter(([request]) => request.name === "save_lobu_app_state")).toHaveLength(0);
		} finally { warn.mockRestore(); }
	});
});
